package net.officefloor.hq.app.invoice;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.ManyToOne;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.math.RoundingMode;

/** One thing an invoice charges for: a description, how many (in what unit), and the price of each. */
@Entity
@Table(name = "invoice_line_item")
public class InvoiceLineItem {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @ManyToOne(fetch = FetchType.LAZY, optional = false)
    @JoinColumn(name = "invoice_id", nullable = false)
    private Invoice invoice;

    @Column(nullable = false)
    private String description;

    @Column(nullable = false, precision = 10, scale = 2)
    private BigDecimal qty;

    @Column(length = 50)
    private String unit;

    @Column(name = "unit_price", nullable = false, precision = 14, scale = 4)
    private BigDecimal unitPrice;

    @Column(name = "tax_exempt", nullable = false)
    private boolean taxExempt;

    @Column(name = "discount_pct", nullable = false, precision = 5, scale = 2)
    private BigDecimal discountPct = BigDecimal.ZERO;

    protected InvoiceLineItem() {
    }

    InvoiceLineItem(Invoice invoice, String description, BigDecimal qty, String unit, BigDecimal unitPrice,
            boolean taxExempt, BigDecimal discountPct) {
        this.invoice = invoice;
        this.description = description;
        this.qty = qty;
        this.unit = unit;
        this.unitPrice = unitPrice;
        this.taxExempt = taxExempt;
        this.discountPct = discountPct;
    }

    void update(String description, BigDecimal qty, String unit, BigDecimal unitPrice, boolean taxExempt,
            BigDecimal discountPct) {
        this.description = description;
        this.qty = qty;
        this.unit = unit;
        this.unitPrice = unitPrice;
        this.taxExempt = taxExempt;
        this.discountPct = discountPct;
    }

    public Long getId() {
        return id;
    }

    public Invoice getInvoice() {
        return invoice;
    }

    public String getDescription() {
        return description;
    }

    public BigDecimal getQty() {
        return qty;
    }

    /** What the quantity counts, such as hours; null when the line does not say. */
    public String getUnit() {
        return unit;
    }

    public BigDecimal getUnitPrice() {
        return unitPrice;
    }

    /** Whether this line is tax-free: it is not taxable. */
    public boolean isTaxExempt() {
        return taxExempt;
    }

    /** The percentage this line takes off what it charges; zero when it has no discount of its own. */
    public BigDecimal getDiscountPct() {
        return discountPct;
    }

    /** Quantity times unit price, rounded to the cent, before this line's own discount. */
    public BigDecimal getGrossAmount() {
        return qty.multiply(unitPrice).setScale(2, RoundingMode.HALF_UP);
    }

    /**
     * What this line charges: quantity times unit price less the line's own discount, each rounded to the
     * cent on its own before lines are added up.
     */
    public BigDecimal getAmount() {
        BigDecimal gross = getGrossAmount();
        return gross.subtract(gross.multiply(discountPct).divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_UP));
    }
}
package net.officefloor.hq.app.invoice;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.ManyToOne;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.math.RoundingMode;

/** One discount on an invoice: either a percentage or a flat amount taken off its subtotal, never both. */
@Entity
@Table(name = "invoice_discount")
public class InvoiceDiscount {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @ManyToOne(fetch = FetchType.LAZY, optional = false)
    @JoinColumn(name = "invoice_id", nullable = false)
    private Invoice invoice;

    @Column(name = "discount_pct", nullable = false, precision = 5, scale = 2)
    private BigDecimal discountPct = BigDecimal.ZERO.setScale(2);

    @Column(name = "discount_amount", nullable = false, precision = 12, scale = 2)
    private BigDecimal discountAmount = BigDecimal.ZERO.setScale(2);

    /** The most a percentage discount takes off; null when it is not capped. */
    @Column(name = "discount_cap", precision = 12, scale = 2)
    private BigDecimal discountCap;

    protected InvoiceDiscount() {
    }

    InvoiceDiscount(Invoice invoice, BigDecimal discountPct, BigDecimal discountAmount) {
        this(invoice, discountPct, discountAmount, null);
    }

    InvoiceDiscount(Invoice invoice, BigDecimal discountPct, BigDecimal discountAmount, BigDecimal discountCap) {
        if (discountPct.signum() != 0 && discountAmount.signum() != 0) {
            throw new IllegalArgumentException("A discount is either a percentage or a flat amount, not both");
        }
        if (discountCap != null && discountPct.signum() == 0) {
            throw new IllegalArgumentException("Only a percentage discount can be capped");
        }
        this.invoice = invoice;
        this.discountPct = discountPct.setScale(2, RoundingMode.HALF_UP);
        this.discountAmount = discountAmount.setScale(2, RoundingMode.HALF_UP);
        this.discountCap = discountCap == null ? null : discountCap.setScale(2, RoundingMode.HALF_UP);
    }

    public Long getId() {
        return id;
    }

    /** The percentage taken off the subtotal; zero when this is a flat discount. */
    public BigDecimal getDiscountPct() {
        return discountPct;
    }

    /** The flat amount asked to be taken off the subtotal; zero when this is a percentage discount. */
    public BigDecimal getDiscountAmount() {
        return discountAmount;
    }

    /** The most this percentage discount takes off; null when it is not capped. */
    public BigDecimal getDiscountCap() {
        return discountCap;
    }

    /** Whether this discount is a percentage of the subtotal rather than a flat amount. */
    public boolean isPercentage() {
        return discountPct.signum() > 0;
    }
}
package net.officefloor.hq.app.currency;

import java.math.BigDecimal;
import java.math.RoundingMode;

/**
 * How a currency's amounts are rounded when shown: to the nearest multiple of its rounding step, never finer than its
 * smallest unit, halves away from zero. It is the rule an invoice's figures are shown with, so totals built from
 * rounded figures agree to the cent with the figures they add up.
 */
public record MoneyRule(BigDecimal step) {

    /** The rule for a currency nothing is known about: whole cents. */
    public static final MoneyRule CENTS = new MoneyRule(new BigDecimal("0.01"));

    static MoneyRule of(Currency currency) {
        BigDecimal smallest = BigDecimal.ONE.movePointLeft(currency.getDecimals());
        return new MoneyRule(currency.getRoundingStep().max(smallest));
    }

    /** The amount rounded to this rule, in cents; null stays null. */
    public BigDecimal round(BigDecimal amount) {
        if (amount == null) {
            return null;
        }
        BigDecimal cents = amount.setScale(2, RoundingMode.HALF_UP);
        return cents.divide(step, 0, RoundingMode.HALF_UP).multiply(step).setScale(2, RoundingMode.HALF_UP);
    }
}
package net.officefloor.hq.app.currency;

import java.util.List;
import net.officefloor.hq.app.Audit;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
public class CurrencyService {

    private final CurrencyRepository currencies;
    private final Audit audit;

    public CurrencyService(CurrencyRepository currencies, Audit audit) {
        this.currencies = currencies;
        this.audit = audit;
    }

    /** The known currencies, the original ones first. */
    @Transactional(readOnly = true)
    public List<CurrencyResponse> list() {
        return currencies.findAll().stream()
                .sorted((a, b) -> Currency.ORDER.compare(a.getCode(), b.getCode()))
                .map(CurrencyResponse::from)
                .toList();
    }

    /** Whether the code names a known currency. */
    @Transactional(readOnly = true)
    public boolean exists(String code) {
        return code != null && currencies.existsById(code);
    }

    /** The rule the currency's amounts are rounded by; whole cents for an unknown currency. */
    @Transactional(readOnly = true)
    public MoneyRule ruleFor(String code) {
        return code == null ? MoneyRule.CENTS : currencies.findById(code).map(MoneyRule::of).orElse(MoneyRule.CENTS);
    }

    /** Changes the step a currency's amounts are rounded to, recording the change in the audit log. */
    @Transactional
    public CurrencyResponse changeRounding(String code, CurrencyRoundingRequest request) {
        Currency currency = currencies.findById(code)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown currency"));
        if (currency.getRoundingStep().compareTo(request.roundingStep()) != 0) {
            currency.setRoundingStep(request.roundingStep());
            currencies.flush();
            audit.record("CURRENCY_ROUNDING_CHANGED code=" + code + " step=" + currency.getRoundingStep().toPlainString());
        }
        return CurrencyResponse.from(currency);
    }
}
package net.officefloor.hq.app.currency;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.Comparator;
import java.util.List;

/**
 * A currency clients can be billed in, by ISO 4217 code, with the symbol its amounts are shown with and
 * the step they are rounded to when shown (0.05 rounds to the nearest five cents), and the number of
 * decimal places they are shown with (yen has none).
 */
@Entity
@Table(name = "currency")
public class Currency {

    /** The currency a client is billed in unless another is chosen. */
    public static final String DEFAULT = "USD";

    /** The original currencies come first in their usual order; any others follow by code. */
    private static final List<String> STANDARD = List.of("USD", "EUR", "GBP", "CAD", "AUD");

    public static final Comparator<String> ORDER = Comparator
            .comparingInt((String code) -> STANDARD.contains(code) ? STANDARD.indexOf(code) : STANDARD.size())
            .thenComparing(Comparator.naturalOrder());

    @Id
    private String code;

    @Column(nullable = false)
    private String symbol;

    @Column(name = "rounding_step", nullable = false, precision = 10, scale = 2)
    private BigDecimal roundingStep = new BigDecimal("0.01");

    @Column(nullable = false)
    private int decimals = 2;

    protected Currency() {
    }

    public String getCode() {
        return code;
    }

    public String getSymbol() {
        return symbol;
    }

    public BigDecimal getRoundingStep() {
        return roundingStep;
    }

    public int getDecimals() {
        return decimals;
    }

    public void setRoundingStep(BigDecimal roundingStep) {
        this.roundingStep = roundingStep.setScale(2, RoundingMode.HALF_UP);
    }
}
package net.officefloor.hq.app.invoice;

/**
 * Lifecycle stage of an invoice: DRAFT -> SENT -> PARTIAL -> PAID. Once sent, the stage is worked
 * out from the payments and credit notes recorded against the invoice. A sent invoice with nothing paid against it can
 * instead be cancelled, making it VOID: it stays on record but is no longer owed. A sent or part-paid invoice that
 * will never be paid can be written off as bad debt, making it WRITTEN_OFF: likewise kept on record but no longer owed.
 */
public enum InvoiceStatus {
    DRAFT,
    SENT,
    PARTIAL,
    PAID,
    VOID,
    WRITTEN_OFF;

    /** Whether payments can still be recorded against an invoice at this stage. */
    public boolean isOwing() {
        return this == SENT || this == PARTIAL;
    }

    /** Whether an invoice at this stage is closed without being paid (cancelled or written off), so nothing is owed. */
    public boolean isClosedUnpaid() {
        return this == VOID || this == WRITTEN_OFF;
    }
}

