172	    /** The discounts on this invoice, in the order they were added. */
173	    public List<InvoiceDiscount> getDiscounts() {
174	        return List.copyOf(discounts);
175	    }
176	
177	    /**
178	     * The percentages taken off the subtotal, added up (never more than 100); zero when there is no
179	     * percentage discount.
180	     */
181	    public BigDecimal getDiscountPct() {
182	        return discounts.stream().map(InvoiceDiscount::getDiscountPct).reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add)
183	                .min(BigDecimal.valueOf(100).setScale(2));
184	    }
185	
186	    /** The flat amounts asked to be taken off the subtotal, added up; zero when there is no flat discount. */
187	    public BigDecimal getDiscountAmount() {
188	        return discounts.stream().map(InvoiceDiscount::getDiscountAmount).reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
189	    }
190	
191	    /**
192	     * How much one of this invoice's discounts actually takes off the subtotal, to the cent. The
193	     * percentages are taken first, each its share of the subtotal (never more than its cap, if it has
194	     * one), then the flat amounts in the order they were added; none takes off more than is left after
195	     * those before it.
196	     */
197	    public BigDecimal discountTakenBy(InvoiceDiscount discount) {
198	        BigDecimal subtotal = getSubtotal();
199	        BigDecimal left = subtotal;
200	        for (InvoiceDiscount d : discountsInOrderTaken()) {
201	            BigDecimal wanted = d.isPercentage() ? percentWanted(subtotal, d) : d.getDiscountAmount();
202	            BigDecimal taken = wanted.min(left.max(BigDecimal.ZERO.setScale(2)));
203	            if (d == discount) {
204	                return taken;
205	            }
206	            left = left.subtract(taken);
207	        }
208	        return BigDecimal.ZERO.setScale(2);
209	    }
