211	    /** What a percentage discount asks to take off the subtotal: its share, never more than its cap. */
212	    private static BigDecimal percentWanted(BigDecimal subtotal, InvoiceDiscount discount) {
213	        BigDecimal share = percentOf(subtotal, discount.getDiscountPct());
214	        return isCappedAt(subtotal, discount) ? share.min(discount.getDiscountCap()) : share;
215	    }
216	
217	    /** Whether a discount's cap limits what it takes off the given subtotal. */
218	    private static boolean isCappedAt(BigDecimal subtotal, InvoiceDiscount discount) {
219	        return discount.getDiscountCap() != null
220	                && percentOf(subtotal, discount.getDiscountPct()).compareTo(discount.getDiscountCap()) > 0;
221	    }
222	
223	    /** The percentage discounts first, then the flat ones, each in the order they were added. */
224	    private List<InvoiceDiscount> discountsInOrderTaken() {
225	        List<InvoiceDiscount> ordered = new ArrayList<>(discounts.stream().filter(InvoiceDiscount::isPercentage).toList());
226	        ordered.addAll(discounts.stream().filter(d -> !d.isPercentage()).toList());
227	        return ordered;
228	    }
