280	     * each taxable line rounded to the cent, added up.
281	     */
282	    public BigDecimal getTax() {
283	        return sumOverTaxableLines(this::taxOn);
284	    }
285	
286	    /** The levy (second tax) percentage added on top of the sales tax; zero when there is no levy. */
287	    public BigDecimal getLevyPct() {
288	        return levyPct;
289	    }
290	
291	    /**
292	     * How much levy is added on the taxable base (or is inside it, when tax-inclusive): the levy on each
293	     * taxable line rounded to the cent, added up.
294	     */
295	    public BigDecimal getLevy() {
296	        return sumOverTaxableLines(this::levyOn);
297	    }
298	
299	    /** The flat amount (such as a handling fee) added to the total after tax; zero when there is none. */
300	    public BigDecimal getSurcharge() {
301	        return surcharge;
302	    }
303	
304	    /** The least this invoice bills; zero when there is no minimum charge. */
305	    public BigDecimal getMinimumCharge() {
306	        return minimumCharge;
307	    }
308	
309	    /**
310	     * What the invoice comes to before any minimum charge: the subtotal less the discount plus the tax and
311	     * levy (unless they are inside the prices), plus the surcharge.
312	     */
313	    public BigDecimal getNetTotal() {
314	        BigDecimal discounted = getSubtotal().subtract(getDiscount());
315	        return (taxInclusive ? discounted : discounted.add(getTax()).add(getLevy())).add(surcharge);
316	    }
317	
318	    /** Whether the net total came out under the minimum charge, so the minimum is billed instead. */
319	    public boolean isMinimumApplied() {
320	        return getNetTotal().compareTo(minimumCharge) < 0;
321	    }
322	
323	    /** The taxable lines (leaving out tax-free ones), each less the discount taken off it, added up. */
324	    private BigDecimal getDiscountedTaxable() {
325	        return sumOverTaxableLines(line -> line);
326	    }
327	
328	    /**
329	     * Works a figure out on each taxable line after its discount, to the cent, and adds them up. A
330	     * tax-exempt invoice has no taxable lines.
331	     */
332	    private BigDecimal sumOverTaxableLines(UnaryOperator<BigDecimal> perLine) {
333	        return lineItems.stream().filter(l -> !taxExempt && !l.isTaxExempt()).map(InvoiceLineItem::getAmount)
334	                .map(amount -> perLine.apply(amount.subtract(discountOn(amount))))
335	                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
336	    }
337	
338	    /**
339	     * The part of a tax-inclusive price that is the given percentage, worked back out of it: the price
340	     * divided in proportion to the sales tax and levy rates it includes (e.g. 20% tax in 120 is 20).
341	     */
342	    private BigDecimal includedIn(BigDecimal price, BigDecimal pct) {
343	        BigDecimal grossPct = BigDecimal.valueOf(100).add(taxPct).add(levyPct);
344	        return price.multiply(pct).divide(grossPct, 2, RoundingMode.HALF_UP);
345	    }
346	
347	    /** The percentage taken off what is owed when paid early; zero when none is offered. */
348	    public BigDecimal getEarlyPaymentPct() {
349	        return earlyPaymentPct;
350	    }
351	
352	    /**
353	     * How many days after being issued the invoice must be paid within to get the early-payment discount:
354	     * the early-payment window in its client's payment terms; zero when the client has none.
355	     */
356	    public int getEarlyPaymentDays() {
357	        Integer window = project.getClient().getEarlyPaymentWindowDays();
358	        return window != null ? window : 0;
359	    }
360	
361	    /** Whether an early-payment discount is offered: a percentage off when paid within the client's early-payment window. */
362	    public boolean offersEarlyPayment() {
363	        return earlyPaymentPct.signum() > 0 && getEarlyPaymentDays() > 0;
364	    }
365	
366	    /** The last day the invoice can be paid to get the early-payment discount; null when none is offered. */
367	    public LocalDate getEarlyPaymentBy() {
368	        return offersEarlyPayment() ? issuedDate.plusDays(getEarlyPaymentDays()) : null;
369	    }
370	
371	    /**
372	     * The reduced amount to pay when settling early: the amount less the early-payment percentage of it,
373	     * to the cent; null when no early-payment discount is offered.
374	     */
375	    public BigDecimal getEarlyPaymentAmount() {
376	        return offersEarlyPayment() ? amount.subtract(percentOf(amount, earlyPaymentPct)) : null;
377	    }
378	
379	    /** The percentage of the amount given back when paid before the due date; zero when none is offered. */
380	    public BigDecimal getRebatePct() {
381	        return rebatePct;
382	    }
383	
384	    /** The settlement rebate for paying before the due date: the rebate percentage of the amount, to the cent; null when none is offered. */
385	    public BigDecimal getRebate() {
386	        return rebatePct.signum() > 0 ? percentOf(amount, rebatePct) : null;
387	    }
388	
389	    /** The settlement rebate given back because the client paid early enough; zero when it has not been earned. */
390	    public BigDecimal getRebateTaken() {
391	        return rebateTaken;
392	    }
393	
394	    /** Whether the settlement rebate has been earned, so the invoice settles for the reduced amount. */
395	    public boolean isRebateTaken() {
396	        return rebateTaken.signum() > 0;
397	    }
398	
399	    /**
400	     * The reduced amount the client actually needed to pay once the rebate was earned: the amount less the rebate
401	     * given back; null when no rebate has been earned.
402	     */
403	    public BigDecimal getRebatedAmount() {
404	        return isRebateTaken() ? amount.subtract(rebateTaken) : null;
405	    }
406	
407	    /**
408	     * Gives back the settlement rebate when what was paid before the due date, together with the credit and any
409	     * part written off, has cleared the amount less the rebate. Once taken it stays taken.
410	     */
411	    public void takeRebateIfEarned(BigDecimal paidBeforeDue, BigDecimal credited) {
412	        BigDecimal rebate = getRebate();
413	        if (rebate == null || isRebateTaken() || dueDate == null) {
414	            return;
415	        }
416	        if (paidBeforeDue.add(credited).add(writeOffAmount).compareTo(amount.subtract(rebate)) >= 0) {
417	            this.rebateTaken = rebate;
418	        }
419	    }
420	
421	    public InvoiceStatus getStatus() {
422	        return status;
423	    }
424	
425	    public LocalDate getIssuedDate() {
426	        return issuedDate;
427	    }
428	
429	    public LocalDate getDueDate() {
430	        return dueDate;
431	    }
432	
433	    public List<InvoiceLineItem> getLineItems() {
434	        return List.copyOf(lineItems);
435	    }
436	
437	    /** Adds a line to this invoice and reworks its amount to include what the line charges. */
438	    public InvoiceLineItem addLineItem(String description, BigDecimal qty, String unit, BigDecimal unitPrice) {
439	        return addLineItem(description, qty, unit, unitPrice, false, BigDecimal.ZERO);
440	    }
441	
442	    /**
443	     * Adds a line, taxable or tax-free and with any discount of its own, to this invoice and reworks its
444	     * amount to include what the line charges after that discount.
445	     */
446	    public InvoiceLineItem addLineItem(String description, BigDecimal qty, String unit, BigDecimal unitPrice,
447	            boolean taxExempt, BigDecimal discountPct) {
448	        InvoiceLineItem item = new InvoiceLineItem(this, description, qty, unit, unitPrice, taxExempt, discountPct);
449	        lineItems.add(item);
450	        recalculateAmount();
451	        return item;
452	    }
453	
454	    /** Changes one of this invoice's lines and reworks its amount to match. */
455	    public void updateLineItem(InvoiceLineItem item, String description, BigDecimal qty, String unit,
456	            BigDecimal unitPrice, boolean taxExempt, BigDecimal discountPct) {
457	        item.update(description, qty, unit, unitPrice, taxExempt, discountPct);
458	        recalculateAmount();
459	    }
460	
461	    /** Removes a line from this invoice and reworks its amount to no longer include what the line charged. */
462	    public void removeLineItem(InvoiceLineItem item) {
463	        lineItems.remove(item);
464	        recalculateAmount();
465	    }
466	
467	    /** The line on this invoice with the given id, if there is one. */
468	    public Optional<InvoiceLineItem> findLineItem(Long lineItemId) {
469	        return lineItems.stream().filter(l -> l.getId().equals(lineItemId)).findFirst();
470	    }
471	
472	    /** Replaces this invoice's discounts with a single percentage and reworks its amount to match. */
473	    public void applyDiscount(BigDecimal discountPct) {
474	        applyDiscount(discountPct, BigDecimal.ZERO);
475	    }
476	
477	    /**
478	     * Replaces this invoice's discounts with a single one, either a percentage or a flat amount (the other
479	     * being zero; zero for both leaves no discount), and reworks its amount to match.
480	     */
481	    public void applyDiscount(BigDecimal discountPct, BigDecimal discountAmount) {
482	        applyDiscount(discountPct, discountAmount, null);
483	    }
484	
485	    /**
486	     * Replaces this invoice's discounts with a single one, either a percentage (optionally capped at the
487	     * most it takes off) or a flat amount, and reworks its amount to match.
488	     */
489	    public void applyDiscount(BigDecimal discountPct, BigDecimal discountAmount, BigDecimal discountCap) {
490	        InvoiceDiscount discount = new InvoiceDiscount(this, discountPct, discountAmount, discountCap);
491	        discounts.clear();
492	        if (discountPct.signum() != 0 || discountAmount.signum() != 0) {
493	            discounts.add(discount);
494	        }
495	        recalculateAmount();
496	    }
497	
498	    /**
499	     * Adds another discount to this invoice, either a percentage or a flat amount (the other being zero),
500	     * and reworks its amount to match.
501	     */
502	    public InvoiceDiscount addDiscount(BigDecimal discountPct, BigDecimal discountAmount) {
503	        return addDiscount(discountPct, discountAmount, null);
504	    }
505	
506	    /**
507	     * Adds another discount to this invoice, either a percentage (optionally capped at the most it takes
508	     * off) or a flat amount, and reworks its amount to match.
509	     */
510	    public InvoiceDiscount addDiscount(BigDecimal discountPct, BigDecimal discountAmount, BigDecimal discountCap) {
511	        if (discountPct.signum() == 0 && discountAmount.signum() == 0) {
512	            throw new IllegalArgumentException("A discount takes off a percentage or a flat amount");
513	        }
514	        InvoiceDiscount discount = new InvoiceDiscount(this, discountPct, discountAmount, discountCap);
515	        discounts.add(discount);
516	        recalculateAmount();
517	        return discount;
518	    }
519	
520	    /** Removes a discount from this invoice and reworks its amount to match. */
521	    public void removeDiscount(InvoiceDiscount discount) {
522	        discounts.remove(discount);
523	        recalculateAmount();
524	    }
525	
526	    /** The discount on this invoice with the given id, if there is one. */
527	    public Optional<InvoiceDiscount> findDiscount(Long discountId) {
528	        return discounts.stream().filter(d -> d.getId().equals(discountId)).findFirst();
529	    }
530	
531	    /** Sets the sales tax percentage added to this invoice and reworks its amount to match. */
532	    public void applyTax(BigDecimal taxPct) {
533	        this.taxPct = taxPct.setScale(2, RoundingMode.HALF_UP);
534	        recalculateAmount();
535	    }
536	
537	    /** Sets whether this invoice's prices already include tax and reworks its amount to match. */
538	    public void applyTaxInclusive(boolean taxInclusive) {
539	        this.taxInclusive = taxInclusive;
540	        recalculateAmount();
541	    }
542	
543	    /** Sets whether this invoice is for a tax-exempt client and reworks its amount to match. */
544	    public void applyTaxExempt(boolean taxExempt) {
545	        this.taxExempt = taxExempt;
546	        recalculateAmount();
547	    }
548	
549	    /** Sets the levy (second tax) percentage added to this invoice and reworks its amount to match. */
550	    public void applyLevy(BigDecimal levyPct) {
551	        this.levyPct = levyPct.setScale(2, RoundingMode.HALF_UP);
552	        recalculateAmount();
553	    }
554	
555	    /** Sets the flat surcharge (such as a handling fee) added to this invoice and reworks its amount to match. */
556	    public void applySurcharge(BigDecimal surcharge) {
557	        this.surcharge = surcharge.setScale(2, RoundingMode.HALF_UP);
558	        recalculateAmount();
559	    }
560	
561	    /** Sets the minimum charge billed on this invoice and reworks its amount to match. */
562	    public void applyMinimumCharge(BigDecimal minimumCharge) {
563	        this.minimumCharge = minimumCharge.setScale(2, RoundingMode.HALF_UP);
564	        recalculateAmount();
565	    }
566	
567	    /** Sets the late fee charged for each day this invoice is overdue. It does not change the amount invoiced. */
568	    public void applyLateFee(BigDecimal lateFeePerDay) {
569	        this.lateFeePerDay = lateFeePerDay.setScale(2, RoundingMode.HALF_UP);
570	    }
571	
572	    public BigDecimal getLateFeePerDay() {
573	        return lateFeePerDay;
574	    }
575	
576	    /** Sets the interest charged for each day an instalment of this invoice is paid late. */
577	    public void applyInstalmentInterest(BigDecimal interestPerDay) {
578	        this.instalmentInterestPerDay = interestPerDay.setScale(2, RoundingMode.HALF_UP);
579	    }
580	
581	    public BigDecimal getInstalmentInterestPerDay() {
582	        return instalmentInterestPerDay;
583	    }
584	
585	    /** Sets the percentage of this invoice held back as retention. It does not change the amount invoiced. */
586	    public void applyRetention(BigDecimal retentionPct) {
587	        this.retentionPct = retentionPct.setScale(2, RoundingMode.HALF_UP);
588	    }
589	
590	    public BigDecimal getRetentionPct() {
591	        return retentionPct;
592	    }
593	
594	    /** Releases the retention held back, so it becomes due. The percentage is kept on record. */
595	    public void releaseRetention() {
596	        this.retentionReleased = true;
597	    }
598	
599	    public boolean isRetentionReleased() {
600	        return retentionReleased;
601	    }
602	
603	    /**
604	     * The amount held back as retention: the retention percentage of the amount invoiced, or nothing once
605	     * the retention has been released.
606	     */
607	    public BigDecimal getRetention() {
608	        return retentionReleased ? BigDecimal.ZERO.setScale(2) : percentOf(amount, retentionPct);
609	    }
610	
611	    /** What is due now: the amount invoiced less the retention held back. */
612	    public BigDecimal getDueNow() {
613	        return amount.subtract(getRetention());
614	    }
615	
616	    /**
617	     * How many days past its due date the invoice is on the given day; zero unless it has been sent and
618	     * is still owed (sent or part paid).
619	     */
620	    public long daysLate(InvoiceStatus status, LocalDate today) {
621	        if (status != InvoiceStatus.SENT && status != InvoiceStatus.PARTIAL) {
622	            return 0;
623	        }
624	        return Math.max(0, ChronoUnit.DAYS.between(dueDate, today));
625	    }
626	
627	    /** The late fee accrued by the given day: the fee per day times the days the invoice is overdue. */
628	    public BigDecimal lateFee(InvoiceStatus status, LocalDate today) {
629	        return lateFeePerDay.multiply(BigDecimal.valueOf(daysLate(status, today))).setScale(2, RoundingMode.HALF_UP);
630	    }
631	
632	    /**
633	     * Sets the early-payment discount offered on this invoice: the percentage taken off what is owed if it is
634	     * paid within its client's early-payment window. It does not change the amount owed.
635	     */
636	    public void applyEarlyPayment(BigDecimal earlyPaymentPct) {
637	        this.earlyPaymentPct = earlyPaymentPct.setScale(2, RoundingMode.HALF_UP);
638	    }
639	
640	    /**
641	     * Sets the settlement rebate offered on this invoice: the percentage of the amount given back if it is
642	     * paid before the due date. It does not change the amount invoiced.
643	     */
644	    public void applyRebate(BigDecimal rebatePct) {
645	        this.rebatePct = rebatePct.setScale(2, RoundingMode.HALF_UP);
646	    }
647	
648	    /**
649	     * The discount taken off one line, to the cent: the uncapped percentages together, plus its share of
650	     * what the flat amounts and the capped percentages take off in proportion to what the line charges
651	     * out of the subtotal.
652	     */
653	    private BigDecimal discountOn(BigDecimal line) {
654	        BigDecimal subtotal = getSubtotal();
655	        BigDecimal pct = percentOf(line, uncappedPct(subtotal));
656	        if (subtotal.signum() == 0) {
657	            return pct;
658	        }
659	        BigDecimal flatShare = sharedDiscount(subtotal).multiply(line).divide(subtotal, 2, RoundingMode.HALF_UP);
660	        return pct.add(flatShare);
661	    }
662	
663	    /** The percentages not limited by a cap, added up (never more than 100). */
664	    private BigDecimal uncappedPct(BigDecimal subtotal) {
665	        return discounts.stream().filter(d -> d.isPercentage() && !isCappedAt(subtotal, d)).map(InvoiceDiscount::getDiscountPct)
666	                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add).min(BigDecimal.valueOf(100).setScale(2));
667	    }
668	
669	    /**
670	     * What the flat discounts and the capped percentages actually take off the subtotal together, shared
671	     * across the lines in proportion to what each charges.
672	     */
673	    private BigDecimal sharedDiscount(BigDecimal subtotal) {
674	        return discounts.stream().filter(d -> !d.isPercentage() || isCappedAt(subtotal, d)).map(this::discountTakenBy)
675	                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
676	    }
677	
678	    /** The sales tax on one discounted taxable line (or inside it, when tax-inclusive), to the cent. */
679	    private BigDecimal taxOn(BigDecimal line) {
680	        return taxInclusive ? includedIn(line, taxPct) : percentOf(line, taxPct);
681	    }
682	
683	    /** The levy on one discounted taxable line (or inside it, when tax-inclusive), to the cent. */
684	    private BigDecimal levyOn(BigDecimal line) {
685	        return taxInclusive ? includedIn(line, levyPct) : percentOf(line, levyPct);
686	    }
687	
688	    private static BigDecimal percentOf(BigDecimal base, BigDecimal pct) {
689	        return base.multiply(pct).divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_UP);
690	    }
691	
692	    private void recalculateAmount() {
693	        this.amount = getNetTotal().max(minimumCharge);
694	    }
695	
696	    /** Marks this invoice as sent to the client. */
697	    public void markSent() {
698	        this.status = InvoiceStatus.SENT;
699	    }
700	
701	    /** Cancels this invoice, so it is no longer owed. */
702	    public void markVoid() {
703	        this.status = InvoiceStatus.VOID;
704	    }
705	
706	    /** Flags this invoice as disputed by the client; it still counts as owed. */
707	    public void markDisputed() {
708	        this.disputed = true;
709	    }
710	
711	    public boolean isDisputed() {
712	        return disputed;
713	    }
714	
715	    /** Writes this invoice off as bad debt, so it is no longer owed. */
716	    public void markWrittenOff() {
717	        this.status = InvoiceStatus.WRITTEN_OFF;
718	    }
719	
720	    /** Writes part of this invoice off as bad debt, so that part is no longer owed while the rest still is. */
721	    public void writeOffPart(BigDecimal part) {
722	        this.writeOffAmount = writeOffAmount.add(part).setScale(2, RoundingMode.HALF_UP);
723	    }
724	
725	    public BigDecimal getWriteOffAmount() {
726	        return writeOffAmount;
727	    }
728	
729	    public String getPoNumber() {
730	        return poNumber;
731	    }
732	
733	    public void setPoNumber(String poNumber) {
734	        this.poNumber = poNumber;
735	    }
736	
737	    /**
738	     * What is left to pay on this invoice given the totals paid and credited against it, less any part written
739	     * off and any settlement rebate earned; nothing once it is void or written off.
740	     */
741	    public BigDecimal amountDue(BigDecimal paid, BigDecimal credited) {
742	        return status.isClosedUnpaid() ? BigDecimal.ZERO.setScale(2)
743	                : amount.subtract(paid).subtract(credited).subtract(writeOffAmount).subtract(rebateTaken);
744	    }
745	
746	    /**
747	     * What the client owes on this invoice right now given the totals paid and credited against it: what is
748	     * left to pay less the retention still held back, never below nothing on account of the retention.
749	     */
750	    public BigDecimal dueNow(BigDecimal paid, BigDecimal credited) {
751	        BigDecimal left = amountDue(paid, credited);
752	        if (left.signum() <= 0 || status.isClosedUnpaid()) {
753	            return left;
754	        }
755	        return left.subtract(getRetention()).max(BigDecimal.ZERO.setScale(2));
756	    }
757	
758	    /**
759	     * This invoice's status given the totals paid and credited against it. Once sent, it is PAID when the
760	     * payments, credit notes, any part written off and any settlement rebate earned together clear the amount, PARTIAL once something has been
761	     * paid, credited or written off, otherwise still SENT. Drafts, void and written-off invoices keep their status, as does one marked paid by hand.
762	     */
763	    public InvoiceStatus statusFor(BigDecimal paid, BigDecimal credited) {
764	        if (status == InvoiceStatus.DRAFT || status.isClosedUnpaid()) {
765	            return status;
766	        }
767	        BigDecimal settled = paid.add(credited).add(writeOffAmount).add(rebateTaken);
768	        if (settled.compareTo(amount) >= 0 || (status == InvoiceStatus.PAID && settled.signum() == 0)) {
769	            return InvoiceStatus.PAID;
770	        }
771	        return settled.signum() > 0 ? InvoiceStatus.PARTIAL : InvoiceStatus.SENT;
772	    }
773	
774	    /**
775	     * Works out this sent invoice's status from what is still owed on it after the totals paid and credited against
776	     * it and any part written off: PAID once nothing is left, PARTIAL once something has been settled, otherwise
777	     * still SENT.
778	     */
779	    public void applySettledTotals(BigDecimal paid, BigDecimal credited) {
780	        if (status == InvoiceStatus.DRAFT || status.isClosedUnpaid()) {
781	            throw new IllegalStateException("A " + status.name().toLowerCase() + " invoice cannot be settled");
782	        }
783	        this.status = statusFor(paid, credited);
784	    }
785	}
