package net.officefloor.hq.app.invoice;


/**
 * An invoice, with how much of it the client owes right now after the payments made and credit notes raised
 * against it (nothing once void), the amount held back as retention and not due yet (shown separately), and
 * whether any credit has been put against it. An owing invoice on an instalment plan also carries how it is keeping
 * to its schedule (null otherwise), and whether the client disputes it (still owed, only flagged).
 */
public record InvoiceResponse(Long id, Long projectId, String currency, BigDecimal amount, InvoiceStatus status,
        LocalDate issuedDate, LocalDate dueDate, BigDecimal amountDue,
        BigDecimal retention, boolean creditApplied, ScheduleStatus schedule,
        boolean disputed) {

    static InvoiceResponse from(Invoice invoice, BigDecimal paid, BigDecimal credited) {
        return from(invoice, paid, credited, null);
    }

    static InvoiceResponse from(Invoice invoice, BigDecimal paid, BigDecimal credited, ScheduleStatus schedule) {
        return new InvoiceResponse(invoice.getId(), invoice.getProject().getId(),
                invoice.getCurrency(), invoice.getAmount(),
                invoice.statusFor(paid, credited), invoice.getIssuedDate(), invoice.getDueDate(),
                invoice.dueNow(paid, credited), invoice.getRetention(), credited.signum() > 0, schedule,
                invoice.isDisputed());
    }
}
package net.officefloor.hq.app.invoice;


/**
 * A single invoice together with the line items it is built from: their subtotal, each discount on it
 * (with what it takes off), the percentage discounts and flat amount discounts added up, and what they all take off together, the sales tax percentage, the taxable base it is charged on (the
 * taxable lines after the discount) and what it adds, the levy (second tax) percentage and what it adds
 * on the same base, any flat surcharge (such as a handling fee) added after tax, the amount owed including both taxes and the surcharge, the total before tax, whether the prices already include the taxes
 * (so they are worked back out rather than added on), whether the client is tax exempt (so
 * there is no tax at all), the effective tax rate (the sales tax and levy together as a percentage of
 * the total before tax), any early-payment discount offered (its percentage, the days after issue it
 * must be paid within, the last day to pay, and the reduced amount; null when none is offered), any
 * settlement rebate for paying before the due date (its percentage, and the rebate itself; null when none
 * is offered, and the reduced amount the client actually needed to pay once the rebate was earned; null until
 * then), and the
 * client's tax number (null when the client is not tax registered), the minimum charge, the net total
 * before it, whether the minimum was billed because the net total came out under it, and the total
 * savings (the line discounts and the invoice's discounts added together). A foreign invoice also gives
 * the home currency and its amount converted into it at the exchange rate from the invoice's issue date
 * (null when the invoice is already in the home currency or there is no rate for that date). The late
 * fee charged per day overdue, the days the invoice is overdue as of today (only while sent and still
 * owed), and the late fee that has accrued over them. The percentage held back as retention, the amount
 * it holds back (not due yet, nothing once released), whether it has been released, and what is due now
 * without it. The part written off as bad debt. What the client owes right now after the payments and credit notes against it, less any
 * part written off and any retention still held back. The exchange gain (positive) or loss (negative) realised
 * in the home currency by payments on a foreign invoice, from the rate moving between the invoice's issue date
 * and each payment's date (null when the invoice is in the home currency, has no payments, or a rate is missing).
 * The client's purchase-order number the invoice is raised against (null when none was given).
 */
public record InvoiceDetailResponse(Long id, Long projectId, String currency, BigDecimal amount, BigDecimal totalExTax,
        BigDecimal subtotal,
        BigDecimal discountPct, BigDecimal discountAmount, BigDecimal discount, BigDecimal taxPct, BigDecimal taxableBase, BigDecimal tax,
        BigDecimal levyPct, BigDecimal levy, BigDecimal surcharge, boolean taxInclusive, boolean taxExempt, BigDecimal effectiveTaxPct,
        BigDecimal earlyPaymentPct, int earlyPaymentDays, LocalDate earlyPaymentBy, BigDecimal earlyPaymentAmount,
        BigDecimal rebatePct, BigDecimal rebate, BigDecimal rebatedAmount,
        InvoiceStatus status, LocalDate issuedDate,
        LocalDate dueDate, List<LineItemResponse> lineItems, String clientTaxNumber, List<InvoiceDiscountResponse> discounts,
        BigDecimal minimumCharge, BigDecimal netTotal, boolean minimumApplied, BigDecimal totalSavings,
        String homeCurrency, BigDecimal homeAmount,
        BigDecimal lateFeePerDay, long daysLate, BigDecimal lateFee,
        BigDecimal retentionPct, BigDecimal retention, boolean retentionReleased, BigDecimal dueNow, BigDecimal writeOffAmount, BigDecimal amountDue,
        BigDecimal fxGainLoss, String poNumber) {

    /**
     * The invoice with the given status, as worked out from what has been paid and credited against it, and
     * its amount in the home currency, with any late fee accrued by today.
     */
    static InvoiceDetailResponse from(Invoice invoice, InvoiceStatus status, String homeCurrency, BigDecimal homeAmount,
            LocalDate today, BigDecimal amountDue, BigDecimal fxGainLoss) {
        return new InvoiceDetailResponse(invoice.getId(), invoice.getProject().getId(),
                invoice.getCurrency(), invoice.getAmount(), invoice.getTotalExTax(),
                invoice.getSubtotal(), invoice.getDiscountPct(), invoice.getDiscountAmount(), invoice.getDiscount(),
                invoice.getTaxPct(), invoice.getTaxableBase(), invoice.getTax(),
                invoice.getLevyPct(), invoice.getLevy(), invoice.getSurcharge(), invoice.isTaxInclusive(), invoice.isTaxExempt(),
                invoice.getEffectiveTaxPct(),
                invoice.getEarlyPaymentPct(), invoice.getEarlyPaymentDays(), invoice.getEarlyPaymentBy(),
                invoice.getEarlyPaymentAmount(),
                invoice.getRebatePct(), invoice.getRebate(), invoice.getRebatedAmount(),
                status, invoice.getIssuedDate(), invoice.getDueDate(),
                invoice.getLineItems().stream().map(LineItemResponse::from).toList(),
                invoice.getProject().getClient().getTaxNumber(),
                invoice.getDiscounts().stream().map(d -> new InvoiceDiscountResponse(d.getId(), d.getDiscountPct(),
                        d.getDiscountAmount(), d.getDiscountCap(), invoice.discountTakenBy(d))).toList(),
                invoice.getMinimumCharge(), invoice.getNetTotal(), invoice.isMinimumApplied(),
                invoice.getTotalSavings(), homeCurrency, homeAmount,
                invoice.getLateFeePerDay(), invoice.daysLate(status, today), invoice.lateFee(status, today),
                invoice.getRetentionPct(), invoice.getRetention(), invoice.isRetentionReleased(), invoice.getDueNow(),
                invoice.getWriteOffAmount(), amountDue, fxGainLoss, invoice.getPoNumber());
    }
}
    public ClientStatementResponse statementForClient(Long clientId) {
        Client client = clients.findById(clientId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown client"));
        List<Invoice> found = invoices.findByClientIdWithProject(clientId);
        Map<Long, BigDecimal> paid = paidByInvoice(found);
        Map<Long, BigDecimal> credited = creditedByInvoice(found);
        Function<String, MoneyRule> rules = moneyRules();
        List<ClientStatementResponse.Line> lines = found.stream()
                .map(i -> ClientStatementResponse.Line.from(i, paid.getOrDefault(i.getId(), BigDecimal.ZERO),
                        credited.getOrDefault(i.getId(), BigDecimal.ZERO), rules.apply(i.getCurrency())))
                .toList();
        String home = settings.homeCurrency();
        MoneyRule homeRule = rules.apply(home);
        return ClientStatementResponse.from(client.getId(), client.getName(), client.getCurrency(), lines,
                accountEntries(clientId, found, rules), home, l -> l.issuedDate() == null ? Optional.empty()
                        : fxRates.convert(l.currency(), home, l.issuedDate(), l.amountDue()).map(homeRule::round));
    }

    /**
     * A client's financial summary as at today: the billed, paid and outstanding totals of their statement, and the
     * part of the outstanding left to pay on invoices whose due date has passed.
     */
    @Transactional(readOnly = true)
    public ClientFinancialSummaryResponse financialSummaryForClient(Long clientId) {
        ClientStatementResponse statement = statementForClient(clientId);
        LocalDate today = LocalDate.now(clock);
        BigDecimal overdue = statement.invoices().stream()
                .filter(l -> l.status() != InvoiceStatus.DRAFT && !l.status().isClosedUnpaid())
                .filter(l -> l.dueDate() != null && l.dueDate().isBefore(today) && l.amountDue().signum() > 0)
                .map(ClientStatementResponse.Line::amountDue)
                .reduce(BigDecimal.ZERO, BigDecimal::add)
                .setScale(2, RoundingMode.HALF_UP);
        return new ClientFinancialSummaryResponse(statement.clientId(), statement.currency(), today,
                statement.invoiced(), statement.paid(), statement.outstanding(), overdue);
    }

    /**
     * What a client owed as at the end of the given day: the running account counting only the entries dated on or
     * before it.
     */
    @Transactional(readOnly = true)
    public ClientBalanceAsOfResponse balanceAsOf(Long clientId, LocalDate asOf) {
        Client client = clients.findById(clientId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown client"));
        List<Invoice> found = invoices.findByClientIdWithProject(clientId);
        BigDecimal balance = accountEntries(clientId, found, moneyRules()).stream()
                .filter(e -> e.date() != null && !e.date().isAfter(asOf))
                .map(StatementEntry::change)
                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
        return new ClientBalanceAsOfResponse(client.getId(), client.getCurrency(), asOf, balance);
    }

    /**
     * A client's statement for the given date range (both ends included): the balance owed at the start of it, the
     * entries dated within it in date order each carrying the running balance, the net movement within it, and the
     * balance owed at its end (always the opening balance plus the movements). The payments received within it are
     * also listed and totalled on their own, as are the credit notes issued within it.
     */
    @Transactional(readOnly = true)
    public ClientStatementRangeResponse statementForRange(Long clientId, LocalDate from, LocalDate to) {
        if (to.isBefore(from)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The range must end on or after its start");
        }
        Client client = clients.findById(clientId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown client"));
        List<Invoice> found = invoices.findByClientIdWithProject(clientId);
        Function<String, MoneyRule> rules = moneyRules();
        List<StatementEntry> dated = accountEntries(clientId, found, rules).stream()
                .filter(e -> e.date() != null)
                .sorted(StatementEntry.DATE_ORDER)
                .toList();
        BigDecimal opening = dated.stream()
                .filter(e -> e.date().isBefore(from))
                .map(StatementEntry::change)
                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
        BigDecimal movements = BigDecimal.ZERO.setScale(2);
        List<StatementEntry> within = new ArrayList<>();
        for (StatementEntry entry : dated) {
            if (!entry.date().isBefore(from) && !entry.date().isAfter(to)) {
                movements = movements.add(entry.change());
                within.add(entry.withBalance(opening.add(movements)));
            }
        }
        List<StatementEntry> paymentsWithin = within.stream()
                .filter(e -> e.kind() == StatementEntry.Kind.PAYMENT)
                .toList();
        BigDecimal paymentsTotal = paymentsWithin.stream()
                .map(StatementEntry::credit)
                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
        List<StatementEntry> creditsWithin = within.stream()
                .filter(e -> e.kind() == StatementEntry.Kind.CREDIT_NOTE)
                .toList();
        BigDecimal creditsTotal = creditsWithin.stream()
                .map(StatementEntry::credit)
                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
        List<Invoice> issuedByEnd = found.stream()
                .filter(i -> i.getIssuedDate() != null && !i.getIssuedDate().isAfter(to))
                .toList();
        Map<Long, BigDecimal> paidByEnd = new HashMap<>();
        Map<Long, BigDecimal> creditedByEnd = new HashMap<>();
        List<Long> issuedIds = issuedByEnd.stream().map(Invoice::getId).toList();
        if (!issuedIds.isEmpty()) {
            payments.findByInvoiceIdIn(issuedIds).stream()
                    .filter(p -> p.getDate() == null || !p.getDate().isAfter(to))
                    .forEach(p -> paidByEnd.merge(p.getInvoiceId(), p.getAmount(), BigDecimal::add));
            creditNotes.findByInvoiceIdIn(issuedIds).stream()
                    .filter(n -> !LocalDate.ofInstant(n.getIssuedAt(), ZoneOffset.UTC).isAfter(to))
                    .forEach(n -> creditedByEnd.merge(n.getInvoiceId(), n.getAmount(), BigDecimal::add));
        }
        ClientAgingResponse aging = aging(client, issuedByEnd, paidByEnd, creditedByEnd, rules, to);
        return new ClientStatementRangeResponse(client.getId(), client.getCurrency(), from, to, opening, within,
                movements, opening.add(movements), paymentsWithin, paymentsTotal, creditsWithin, creditsTotal,
                rangeTotal(within, StatementEntry.Kind.INVOICE, StatementEntry::charge),
                rangeTotal(within, StatementEntry.Kind.PAYMENT, StatementEntry::credit), aging);
    }

    /**
     * How old a client's debt is as at today: what is left to pay on each owed invoice (not a draft, void or written
     * off) counted against how many days past its due date it is.
     */
    @Transactional(readOnly = true)
    public ClientAgingResponse agingForClient(Long clientId) {
        Client client = clients.findById(clientId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown client"));
        List<Invoice> found = invoices.findByClientIdWithProject(clientId);
        return aging(client, found, paidByInvoice(found), creditedByInvoice(found), moneyRules(),
                LocalDate.now(clock));
    }

    /**
     * What is left to pay on each owed invoice (not a draft, void or written off) given what was paid and credited
     * against it, counted against how many days past its due date it is as at the given day.
     */
    private ClientAgingResponse aging(Client client, List<Invoice> found, Map<Long, BigDecimal> paid,
            Map<Long, BigDecimal> credited, Function<String, MoneyRule> rules, LocalDate asOf) {
        BigDecimal current = BigDecimal.ZERO.setScale(2);
        BigDecimal days30To60 = BigDecimal.ZERO.setScale(2);
        BigDecimal days60Plus = BigDecimal.ZERO.setScale(2);
        for (Invoice invoice : found) {
            BigDecimal invoicePaid = paid.getOrDefault(invoice.getId(), BigDecimal.ZERO);
            BigDecimal invoiceCredited = credited.getOrDefault(invoice.getId(), BigDecimal.ZERO);
            InvoiceStatus status = invoice.statusFor(invoicePaid, invoiceCredited);
            if (status == InvoiceStatus.DRAFT || status.isClosedUnpaid()) {
                continue;
            }
            BigDecimal due = rules.apply(invoice.getCurrency()).round(invoice.amountDue(invoicePaid, invoiceCredited));
            if (due.signum() <= 0) {
                continue;
            }
            long overdue = invoice.getDueDate() == null ? 0
                    : ChronoUnit.DAYS.between(invoice.getDueDate(), asOf);
            if (overdue > 60) {
                days60Plus = days60Plus.add(due);
            } else if (overdue > 30) {
                days30To60 = days30To60.add(due);
            } else {
                current = current.add(due);
            }
        }
        return new ClientAgingResponse(client.getId(), client.getCurrency(), asOf,
                current.setScale(2, RoundingMode.HALF_UP), days30To60.setScale(2, RoundingMode.HALF_UP),
                days60Plus.setScale(2, RoundingMode.HALF_UP));
    }

    /** The total of the given amount over the entries of the given kind. */
    private static BigDecimal rangeTotal(List<StatementEntry> entries, StatementEntry.Kind kind,
            Function<StatementEntry, BigDecimal> amount) {
        return entries.stream()
                .filter(e -> e.kind() == kind)
                .map(amount)
                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
    }

    /**
     * The entries on a client's running account. Drafts have not been sent and void invoices were cancelled, so
     * neither is charged. A payment made out of held deposits is left out, as the deposit was already credited
     * when it was paid in. Each amount is rounded by the rule of the currency it is in, as the invoice is, so the
     * balances add up to the cent.
     */
    private List<StatementEntry> accountEntries(Long clientId, List<Invoice> found, Function<String, MoneyRule> rules) {
        MoneyRule clientRule = clients.findById(clientId).map(c -> rules.apply(c.getCurrency())).orElse(MoneyRule.CENTS);
        Map<Long, MoneyRule> invoiceRules = new HashMap<>();
        found.forEach(i -> invoiceRules.put(i.getId(), rules.apply(i.getCurrency())));
        List<StatementEntry> entries = new ArrayList<>();
        List<Long> sent = new ArrayList<>();
        Map<Long, String> poNumbers = new HashMap<>();
        for (Invoice invoice : found) {
            if (invoice.getStatus() == InvoiceStatus.DRAFT) {
                continue;
            }
            sent.add(invoice.getId());
            if (invoice.getPoNumber() != null) {
                poNumbers.put(invoice.getId(), invoice.getPoNumber());
            }
            if (invoice.getStatus() != InvoiceStatus.VOID) {
                entries.add(StatementEntry.charge(StatementEntry.Kind.INVOICE, invoice.getId(), invoice.getId(),
                        invoice.getIssuedDate(), "Invoice #" + invoice.getId(), invoiceRules.get(invoice.getId()).round(invoice.getAmount()),
                        invoice.getPoNumber()));
            }
        }
        if (!sent.isEmpty()) {
            for (Payment payment : payments.findByInvoiceIdIn(sent)) {
                if (payment.getDepositApplicationId() == null) {
                    entries.add(StatementEntry.credit(StatementEntry.Kind.PAYMENT, payment.getId(), payment.getInvoiceId(),
                            payment.getDate(), "Payment on invoice #" + payment.getInvoiceId(),
                            invoiceRules.get(payment.getInvoiceId()).round(payment.getAmount()),
                            poNumbers.get(payment.getInvoiceId())));
                }
            }
            for (CreditNote note : creditNotes.findByInvoiceIdIn(sent)) {
                entries.add(StatementEntry.credit(StatementEntry.Kind.CREDIT_NOTE, note.getId(), note.getInvoiceId(),
                        LocalDate.ofInstant(note.getIssuedAt(), ZoneOffset.UTC),
                        "Credit note on invoice #" + note.getInvoiceId(),
                        invoiceRules.get(note.getInvoiceId()).round(note.getAmount()),
                        poNumbers.get(note.getInvoiceId())));
            }
        }
        for (Deposit deposit : deposits.findByClientIdOrderByDateAscIdAsc(clientId)) {
            entries.add(StatementEntry.credit(StatementEntry.Kind.DEPOSIT, deposit.getId(), null, deposit.getDate(),
                    "Deposit", clientRule.round(deposit.getAmount()), null));
        }
        for (Refund refund : refunds.findByClientIdOrderByDateDescIdDesc(clientId)) {
            entries.add(StatementEntry.charge(StatementEntry.Kind.REFUND, refund.getId(), null, refund.getDate(),
                    "Refund", clientRule.round(refund.getAmount()), null));
        }
        return entries;
    }

