package net.officefloor.hq.app.invoice;


/**
 * A client's statement: all of their invoices, each with the project it is for and how much is left
 * to pay, the same invoices grouped by job with what is owed on each job, and the total still owed
 * (what is left to pay across their sent invoices; drafts and void ones are not owed). For the printable
 * summary it also gives the total invoiced on those owed invoices and how much of that has been paid,
 * so the total still owed is what was invoiced less what was paid. It also shows the tax (sales tax and
 * levy) on each job and across the whole statement, again leaving out drafts and void invoices. All of it
 * is in the client's currency, with the total still owed also converted into the home currency at the foot (each
 * invoice at the rate on its issue date; null when a rate is missing). Finally it gives the running account: every invoice, payment, credit note, deposit and
 * refund in date order, each with the balance owed once it is counted.
 */
public record ClientStatementResponse(Long clientId, String clientName, String currency, List<Line> invoices, List<Job> jobs,
        BigDecimal invoiced, BigDecimal paid, BigDecimal outstanding, BigDecimal tax, List<StatementEntry> entries,
        String homeCurrency, BigDecimal homeOutstanding) {

    static ClientStatementResponse from(Long clientId, String clientName, String currency, List<Line> invoices,
            List<StatementEntry> entries, String homeCurrency, Function<Line, Optional<BigDecimal>> toHome) {
        Map<Long, List<Line>> byProject = new LinkedHashMap<>();
        invoices.forEach(l -> byProject.computeIfAbsent(l.projectId(), id -> new ArrayList<>()).add(l));
        List<Job> jobs = byProject.values().stream()
                .map(lines -> new Job(lines.get(0).projectId(), lines.get(0).projectName(), lines, owed(lines), sum(lines, Line::tax)))
                .toList();
        BigDecimal outstanding = owed(invoices);
        BigDecimal invoiced = sum(invoices, Line::amount);
        return new ClientStatementResponse(clientId, clientName, currency, invoices, jobs, invoiced,
                invoiced.subtract(outstanding), outstanding, sum(invoices, Line::tax), runningBalance(entries), homeCurrency,
                homeOwed(invoices, toHome));
    }

    /** What is left to pay across the owed invoices, each converted into the home currency; null if any cannot be. */
    private static BigDecimal homeOwed(List<Line> lines, Function<Line, Optional<BigDecimal>> toHome) {
        BigDecimal total = BigDecimal.ZERO;
        for (Line line : lines) {
            if (line.status() == InvoiceStatus.DRAFT || line.status().isClosedUnpaid()) {
                continue;
            }
            Optional<BigDecimal> converted = toHome.apply(line);
            if (converted.isEmpty()) {
                return null;
            }
            total = total.add(converted.get());
        }
        return total.setScale(2, RoundingMode.HALF_UP);
    }

    /** Puts the entries in date order, each carrying the balance owed once it and those before it are counted. */
    private static List<StatementEntry> runningBalance(List<StatementEntry> entries) {
        List<StatementEntry> ordered = new ArrayList<>();
        BigDecimal balance = BigDecimal.ZERO.setScale(2);
        for (StatementEntry entry : entries.stream().sorted(StatementEntry.DATE_ORDER).toList()) {
            balance = balance.add(entry.change());
            ordered.add(entry.withBalance(balance));
        }
        return ordered;
    }

    /** What is left to pay across the given invoices, leaving out drafts and void ones. */
    private static BigDecimal owed(List<Line> lines) {
        return sum(lines, Line::amountDue);
    }

    /** Adds up the given figure across the invoices that are owed, leaving out drafts and void ones. */
    private static BigDecimal sum(List<Line> lines, Function<Line, BigDecimal> figure) {
        return lines.stream()
                .filter(l -> l.status() != InvoiceStatus.DRAFT && !l.status().isClosedUnpaid())
                .map(figure)
                .reduce(BigDecimal.ZERO, BigDecimal::add)
                .setScale(2, RoundingMode.HALF_UP);
    }

    /** One job on a statement: its invoices, the subtotal still owed on them and the tax charged on them. */
    public record Job(Long projectId, String projectName, List<Line> invoices, BigDecimal subtotal, BigDecimal tax) {
    }

    /** One invoice on a statement; its tax is the sales tax and levy on it. */
    public record Line(Long id, Long projectId, String projectName, String currency, BigDecimal amount, InvoiceStatus status,
            LocalDate issuedDate, LocalDate dueDate, BigDecimal amountDue, BigDecimal tax) {

        /** The invoice's figures, each rounded by its currency's rule as the invoice itself shows them. */
        static Line from(Invoice invoice, BigDecimal paid, BigDecimal credited, MoneyRule rule) {
            return new Line(invoice.getId(), invoice.getProject().getId(), invoice.getProject().getName(),
                    invoice.getCurrency(), rule.round(invoice.getAmount()), invoice.statusFor(paid, credited), invoice.getIssuedDate(), invoice.getDueDate(),
                    rule.round(invoice.amountDue(paid, credited)), rule.round(invoice.getTax()).add(rule.round(invoice.getLevy())));
        }
    }
}
